contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 newLimit) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= 0);
        c.AdjustBetAmounts(newLimit); if (__ESBMC_reverted()) return;
        require(c.currentBetLimit() == newLimit);
        assert(c.ethBalance() == address(c).balance && c.winnersPot() == address(c).balance / 2);
    }
    receive() external payable {}
}

