// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 newLimit) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= 0);
        try c.AdjustBetAmounts(newLimit) {} catch { return; }
        newLimit = c.currentBetLimit();
        assertTrue(c.ethBalance() == address(c).balance && c.winnersPot() == address(c).balance / 2);
    }

    function testFuzz_run(uint256 newLimit) public {
        _run(newLimit);
    }

    receive() external payable {}
}
